import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { searchProducts, adminLogout } from '../services/api';
import { isAdmin, getAdminUser, clearAuthData } from '../util/auth';
import AdminNotifications from './AdminNotifications';

// Direct function definition to avoid import issues
const isAdminAuthenticated = () => {
  const adminToken = localStorage.getItem('adminToken');
  return !!adminToken;
};

const ModernNavbar = ({ cartCount, user, onLogout }) => {
  const navigate = useNavigate();
  const { isDarkMode, toggleTheme } = useTheme();
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  // Check if current page is admin page
  const isAdminPage = window.location.pathname.startsWith('/admin');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showSearch, setShowSearch] = useState(false);
  const [adminAuthState, setAdminAuthState] = useState(isAdminAuthenticated());
  const [isScrolled, setIsScrolled] = useState(false);
  const [placeholderIndex, setPlaceholderIndex] = useState(0);

  // Get gradient colors for fallback background
  const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-800 dark:to-blue-600',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-800 dark:to-amber-600',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-800 dark:to-yellow-600',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-800 dark:to-orange-600',
      curd: 'from-green-200 to-green-400 dark:from-green-800 dark:to-green-600',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-800 dark:to-purple-600',
      cream: 'from-pink-200 to-pink-400 dark:from-pink-800 dark:to-pink-600',
      yogurt: 'from-teal-200 to-teal-400 dark:from-teal-800 dark:to-teal-600',
      lassi: 'from-cyan-200 to-cyan-400 dark:from-cyan-800 dark:to-cyan-600',
      buttermilk: 'from-lime-200 to-lime-400 dark:from-lime-800 dark:to-lime-600',
      sweets: 'from-rose-200 to-pink-300 dark:from-rose-800 dark:to-pink-600',
      cake: 'from-fuchsia-200 to-pink-400 dark:from-fuchsia-800 dark:to-pink-600'
    };
    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-700 dark:to-gray-500';
  };

  // Get emoji for each category
  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙',
      sweets: '🍬',
      cake: '🍰'
    };
    return emojis[category] || '🥛';
  };

  // Derive category from product name if not available
  const deriveCategoryFromName = (name) => {
    const lowerName = name?.toLowerCase() || '';
    if (lowerName.includes('milk')) return 'milk';
    if (lowerName.includes('ghee')) return 'ghee';
    if (lowerName.includes('cheese')) return 'cheese';
    if (lowerName.includes('butter')) return 'butter';
    if (lowerName.includes('curd')) return 'curd';
    if (lowerName.includes('paneer')) return 'paneer';
    if (lowerName.includes('cream') || lowerName.includes('creme') || lowerName.includes('fraiche')) return 'cream';
    if (lowerName.includes('yogurt')) return 'yogurt';
    if (lowerName.includes('lassi')) return 'lassi';
    if (lowerName.includes('buttermilk')) return 'buttermilk';
    return 'milk';
  };

  // Animated placeholder texts
  const placeholderTexts = [
    "",
    "🥛 ",
    "🍯🥛 ",
    "🍦🍯🥛 ",
    "🥤🍦🍯🥛 ",
    "🥣🥤🍦🍯🥛 ",
    "🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊",
    "🥤🍦🍯🥛 ",
    "🍦🍯🥛 ",
    "🍯🥛 ",
    "🥛 ",
    ""
  ];

  // Handle scroll effect
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Placeholder animation effect
  useEffect(() => {
    const interval = setInterval(() => {
      setPlaceholderIndex((prev) => (prev + 1) % placeholderTexts.length);
    }, 2000);

    // Add CSS to hide scrollbar
    const style = document.createElement('style');
    style.textContent = `
      .hide-scrollbar::-webkit-scrollbar {
        display: none;
      }
      .hide-scrollbar {
        -ms-overflow-style: none;
        scrollbar-width: none;
      }
    `;
    document.head.appendChild(style);

    return () => {
      clearInterval(interval);
      document.head.removeChild(style);
    };
  }, [placeholderTexts.length]);

  // Handle notification click
  const handleNotificationClick = (orderId) => {
    if (orderId === 'all') {
      navigate('/admin');
      setTimeout(() => {
        window.location.hash = '#payments';
      }, 100);
    } else {
      navigate('/admin');
      setTimeout(() => {
        sessionStorage.setItem('targetPayment', orderId);
        window.location.hash = '#payments';
      }, 100);
    }
  };

  useEffect(() => {
    const handleStorageChange = () => {
      setAdminAuthState(isAdminAuthenticated());
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('adminAuthChange', handleStorageChange);
    const interval = setInterval(handleStorageChange, 500);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('adminAuthChange', handleStorageChange);
      clearInterval(interval);
    };
  }, []);

  const handleSearch = async (e) => {
    const query = e.target.value;
    setSearchQuery(query);
    setShowSearch(true); // Keep popup open when typing

    if (query.length > 0) {
      try {
        // Get more precise results with smaller limit
        const results = await searchProducts(query, 5);

        // If no results, try with all products as fallback
        if (results.data && results.data.length === 0) {
          const allProducts = await searchProducts('', 10);
          setSearchResults(allProducts.data);
        } else {
          setSearchResults(results.data);
        }
      } catch (error) {
        console.error('Search error:', error);
        setSearchResults([]);
      }
    } else {
      // Clear results but keep popup open
      setSearchResults([]);
    }
  };

  const handleAdminLogout = async () => {
    try {
      await adminLogout();
      clearAuthData();
      setAdminAuthState(false);
      navigate('/admin/login');
    } catch (error) {
      console.error('Admin logout error:', error);
    }
  };

  return (
    <>
      {/* Modern Glass Effect Navbar */}
      <nav className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-300 ${
        isScrolled 
          ? 'bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl border-b border-white/20 dark:border-gray-800/20 shadow-lg' 
          : 'bg-white/90 dark:bg-gray-900/90 backdrop-blur-lg border-b border-white/10 dark:border-gray-800/10'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">

            {/* Logo with Milk Bottle Animation */}
            <Link to="/" className="flex items-center space-x-3 group">
              <div className="relative">
                {/* Milk Bottle Animation */}
                <div className="w-10 h-10 relative">
                  <div className="absolute inset-0 bg-gradient-to-br from-blue-400 to-blue-600 rounded-lg flex items-center justify-center transform transition-transform duration-300 group-hover:rotate-12">
                    {/* Milk Bottle Icon */}
                    <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>
                      <path d="M9 6h6v2H9z" opacity="0.3"/>
                    </svg>
                  </div>
                  {/* Milk Drop Animation */}
                  <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-200 rounded-full animate-bounce opacity-0 group-hover:opacity-100">
                    <div className="w-full h-full bg-blue-300 rounded-full animate-ping"></div>
                  </div>
                </div>
              </div>
              <div className="flex flex-col">
                <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                  MilkMitra
                </span>
                <span className="text-xs text-gray-500 dark:text-gray-400">Fresh Daily</span>
              </div>
            </Link>

            {/* Search Bar */}
            <div className="hidden md:block flex-1 max-w-lg mx-8">
              <div className="relative">
                <div 
                  className="w-full px-5 py-3 pl-12 bg-gradient-to-r from-gray-50 to-gray-100 dark:from-gray-800 dark:to-gray-700 border border-gray-300 dark:border-gray-600 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 text-base cursor-pointer hover:shadow-lg hover:scale-[1.02] transform"
                  onClick={() => setShowSearch(!showSearch)}
                >
                  <input
                    type="text"
                    placeholder={placeholderTexts[placeholderIndex]}
                    value={searchQuery}
                    onChange={handleSearch}
                    onFocus={() => setShowSearch(true)}
                    className="w-full bg-transparent border-none outline-none text-gray-700 dark:text-gray-300 placeholder-gray-500 dark:placeholder-gray-400 pr-10"
                  />

                  {/* Clear Search Button - Modern Cross Icon */}
                  {searchQuery && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setSearchQuery('');
                        setSearchResults([]);
                      }}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 flex items-center justify-center transition-all duration-200 hover:scale-110 group"
                    >
                      <svg 
                        className="w-3.5 h-3.5 text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200 transition-colors" 
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  )}
                </div>
                <svg className="absolute left-4 top-3 w-5 h-5 text-gray-400 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>

                {/* Search Results Dropdown - Modern Design */}
                {showSearch && (
                  <div className="absolute top-full mt-3 w-[140%] left-[-20%] bg-white/95 dark:bg-gray-900/95 backdrop-blur-xl rounded-2xl shadow-[0_20px_60px_-15px_rgba(0,0,0,0.3)] border border-gray-100/50 dark:border-gray-700/50 max-h-[450px] overflow-y-auto transform transition-all duration-300 ease-out animate-in slide-in-from-top-2 fade-in-0 z-50 hide-scrollbar">
                    {/* Modern Header */}
                    <div className="sticky top-0 z-30 bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 text-white p-3.5 rounded-t-2xl shadow-md">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-2.5">
                          <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                            </svg>
                          </div>
                          <span className="font-semibold text-sm tracking-wide">Search Results</span>
                        </div>
                        <button
                          onClick={() => setShowSearch(false)}
                          className="p-1.5 hover:bg-white/25 rounded-full transition-all duration-200 hover:rotate-90"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                          </svg>
                        </button>
                      </div>
                    </div>

                    {/* Results - Modern Styling */}
                    <div className="p-4">
                      {searchResults.length > 0 ? (
                        <div className="space-y-3">
                          {searchResults.map((product, index) => (
                            <Link
                              key={product._id}
                              to={`/products?search=${encodeURIComponent(product.name)}`}
                              className="group flex items-center p-5 bg-gradient-to-r from-white to-gray-50/50 dark:from-gray-800 dark:to-gray-800/50 rounded-2xl border border-gray-100 dark:border-gray-700/50 hover:border-blue-400/50 dark:hover:border-blue-500/50 hover:shadow-lg hover:shadow-blue-500/10 transition-all duration-300 transform hover:scale-[1.02] hover:-translate-y-0.5"
                              onClick={() => {
                                setShowSearch(false);
                                console.log('Searching for product:', product.name);
                              }}
                              style={{ animationDelay: `${index * 60}ms` }}
                            >
                              {/* Product Image with Icon Badge */}
                              <div className="flex-shrink-0 relative">
                                <div className="w-24 h-24 rounded-2xl overflow-hidden shadow-lg">
                                  {/* Animated Background Gradient */}
                                  <div className="absolute inset-0 bg-gradient-to-br from-blue-500/10 via-transparent to-purple-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-1000"></div>

                                  {product.image ? (
                                    <img 
                                      src={product.image} 
                                      alt={product.name} 
                                      className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110"
                                      onError={(e) => {
                                        e.target.style.display = 'none';
                                        e.target.nextSibling.style.display = 'flex';
                                      }}
                                    />
                                  ) : null}

                                  {/* Fallback Image based on category */}
                                  <div 
                                    className={`w-full h-full flex items-center justify-center bg-gradient-to-br ${getCategoryGradient(product.category || deriveCategoryFromName(product.name))} ${product.image ? 'hidden' : 'flex'}`}
                                  >
                                    <span className="text-4xl transform transition-all duration-700 group-hover:scale-110 group-hover:rotate-12">{getCategoryEmoji(product.category || deriveCategoryFromName(product.name))}</span>
                                  </div>
                                </div>

                                {/* Category Icon - Top Right (No Background) */}
